WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, k, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, v), cleaned AS (SELECT id, service, host, log_ts, latency_ms, v, CASE WHEN latency_ms >= 2598 THEN 'High' WHEN latency_ms >= 629 THEN 'Medium' ELSE 'Low' END AS latency_ms_band FROM flattened WHERE log_ts > TIMESTAMP '2025-06-01 06:00:00' AND k IS NOT NULL), valid AS (SELECT id, service, host, log_ts, v, latency_ms_band, CASE WHEN latency_ms >= 2555 THEN 'High' WHEN latency_ms >= 372 THEN 'Medium' ELSE 'Low' END AS latency_ms_level, LOWER(host) AS host_lower FROM cleaned WHERE HOUR(log_ts) BETWEEN 9 AND 12), filtered AS (SELECT *, LENGTH(host) AS host_length FROM valid WHERE log_ts >= DATE '2025-06-01' AND service IN ('search', 'billing')), with_windows AS (SELECT *, DENSE_RANK() OVER (PARTITION BY service ORDER BY host_length) AS host_length_dense_rank, AVG(host_length) OVER (PARTITION BY host ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS host_length_avg_15m, CUME_DIST() OVER (PARTITION BY host ORDER BY host_length NULLS FIRST) AS host_length_cume_dist FROM filtered) SELECT id, service, host, log_ts, v, latency_ms_level, host_lower, host_length_dense_rank, host_length_avg_15m, CASE WHEN host RLIKE '^(h2|h1)$' THEN 'OTHER_ZONE' WHEN host RLIKE '^(h3|h4)$' THEN 'GROUP_A' ELSE 'PRIORITY' END AS host_zone FROM with_windows ORDER BY id DESC
